<script setup lang="ts">
import type { ApiProblem } from '~/types/api'; import type { AcademicTerm } from '~/types/domain'; import type { FormFieldDefinition } from '~/types/forms'
definePageMeta({ middleware: 'auth' }); const route = useRoute(); const { find, update } = useAcademicTerms(); const id = Number(route.params.id); const { data: term } = await useAsyncData(`term-edit-${id}`, () => find(id)); if (!term.value) throw createError({ statusCode: 404 })
const fields: FormFieldDefinition[] = [{ key: 'academic_year', label: 'Academic year', required: true }, { key: 'term', label: 'Term', type: 'select', required: true, options: [{ label: 'First Semester', value: 'first_semester' }, { label: 'Second Semester', value: 'second_semester' }, { label: 'Summer', value: 'summer' }] }, { key: 'start_date', label: 'Start date', type: 'date', required: true }, { key: 'end_date', label: 'End date', type: 'date', required: true }, { key: 'status', label: 'Status', type: 'select', required: true, options: [{ label: 'Upcoming', value: 'upcoming' }, { label: 'Active', value: 'active' }, { label: 'Completed', value: 'completed' }] }]; const errors = ref<Record<string, string[]>>({}); const submitting = ref(false)
async function save(values: Record<string, string | number>) { submitting.value = true; try { await update(id, values as unknown as Partial<AcademicTerm>); await navigateTo(`/academic-terms/${id}`) } catch (error) { const problem = error as ApiProblem; errors.value = problem.errors ?? { form: [problem.message] } } finally { submitting.value = false } }
</script>
<template><div v-if="term" class="page-shell"><PageHeader title="Edit academic term" :description="term.academic_year" /><EntityForm :fields="fields" :initial="{ academic_year: term.academic_year, term: term.term, start_date: term.start_date, end_date: term.end_date, status: term.status }" submit-label="Save changes" :cancel-to="`/academic-terms/${id}`" :submitting="submitting" :server-errors="errors" @submit="save" /></div></template>
